import React, {useEffect, useState} from 'react';
import api from '../api';

export default function AdminPanel(){
  const [deposits,setDeposits]=useState([]);
  useEffect(()=>{ api.get('/deposits/').then(r=>setDeposits(r.data)).catch(()=>{}); },[])
  const confirm = async (id)=>{ await api.post(`/deposits/${id}/confirm/`, {}); alert('تأیید شد'); window.location.reload(); }
  return (
    <div style={{direction:'rtl', padding:20}}>
      <h3>پنل مدیریت</h3>
      <h4>واریزها</h4>
      <ul>
      {deposits.map(d=> (
        <li key={d.id}>{d.user} - {d.amount} - {d.manager_confirmed ? 'تأیید شده' : <button onClick={()=>confirm(d.id)}>تأیید</button>}</li>
      ))}
      </ul>
    </div>
  )
}
